function hasSeenArray(arr, id) {
  return arr.includes(id); // O(n)
}

const seen = new Set();
function track(id) {
  if (seen.has(id)) return false; // O(1) avg
  seen.add(id);
  return true;
}

const meta = new Map();
function getMeta(component) {
  if (!meta.has(component)) {
    meta.set(component, computeExpensive(component));
  }
  return meta.get(component);
}

